    "840 — 848 · 回鹘汗国崩溃：黠戛斯破回鹘牙帐据漠北，回鹘诸部西迁南下，唐会昌年间破乌介可汗": "840–848 · Hãn quốc Hồi Hột sụp đổ: Hiệt Kiết Tư phá nha trướng Hồi Hột chiếm Mạc Bắc, các bộ Hồi Hột dời về tây và nam; thời Hội Xương nhà Đường phá Ô Giới khả hãn",
    "907 — 923 · 后梁：朱温代唐，与河东李氏晋国（含燕云）争衡，十国分立": "907–923 · Hậu Lương: Chu Ôn thay Đường, tranh hùng với nước Tấn họ Lý ở Hà Đông (gồm Yên Vân), mười nước phân lập",
    "923 — 925 · 后唐灭后梁：李存勖定都洛阳统一北方，前蜀、渤海尚存": "923–925 · Hậu Đường diệt Hậu Lương: Lý Tồn Úc đóng đô Lạc Dương thống nhất phương bắc, Tiền Thục, Bột Hải vẫn còn",
    "925 — 934 · 后唐灭前蜀：巴蜀并入后唐版图；926 年契丹灭渤海国": "925–934 · Hậu Đường diệt Tiền Thục: Ba Thục nhập vào Hậu Đường; năm 926 Khiết Đan diệt Bột Hải",
    "934 — 936 · 后蜀自立：孟知祥在成都称帝建后蜀，燕云仍属后唐": "934–936 · Hậu Thục tự lập: Mạnh Tri Tường xưng đế ở Thành Đô lập Hậu Thục, Yên Vân vẫn thuộc Hậu Đường",
    "947 — 951 · 后汉：契丹改国号辽，刘知远建后汉，闽入南唐与吴越": "947–951 · Hậu Hán: Khiết Đan đổi quốc hiệu là Liêu, Lưu Tri Viễn lập Hậu Hán, đất Mân về tay Nam Đường và Ngô Việt",
    "960 — 963 · 北宋立国初年：陈桥兵变建宋，南方诸国与北汉尚未平定": "960–963 · Những năm đầu Bắc Tống: binh biến Trần Kiều lập Tống, các nước phương nam và Bắc Hán chưa bình định",
    "963 — 965 · 平定荆湖：宋军假途灭虢平荆南与湖南": "963–965 · Bình định Kinh Hồ: quân Tống \"giả đạo diệt Quắc\", bình Kinh Nam và Hồ Nam",
    "965 — 971 · 宋灭后蜀：王全斌平蜀，巴蜀并入北宋版图": "965–971 · Tống diệt Hậu Thục: Vương Toàn Bân bình Thục, Ba Thục nhập vào Bắc Tống",
    "971 — 975 · 宋灭南汉：潘美平岭南，两广并入北宋版图": "971–975 · Tống diệt Nam Hán: Phan Mỹ bình Lĩnh Nam, Lưỡng Quảng nhập vào Bắc Tống",
    "975 — 978 · 宋灭南唐：曹彬克金陵，江南并入北宋版图": "975–978 · Tống diệt Nam Đường: Tào Bân hạ Kim Lăng, Giang Nam nhập vào Bắc Tống",
    "978 — 979 · 吴越纳土：钱俶与陈洪进纳土归宋，唯余河东北汉": "978–979 · Ngô Việt nộp đất: Tiền Thục và Trần Hồng Tiến nộp đất về Tống, chỉ còn Bắc Hán ở Hà Đông",
    "979 — 1038 · 宋辽并立：宋太宗灭北汉结束五代十国，澶渊之盟定宋辽边界": "979–1038 · Tống – Liêu cùng tồn tại: Tống Thái Tông diệt Bắc Hán chấm dứt Ngũ Đại Thập Quốc, minh ước Thiền Uyên định biên giới Tống – Liêu",
    "1115 — 1125 · 女真崛起：完颜阿骨打建金，攻克辽上京、东京与辽东": "1115–1125 · Nữ Chân trỗi dậy: Hoàn Nhan A Cốt Đả lập Kim, hạ Thượng Kinh, Đông Kinh của Liêu và Liêu Đông",
    "1125 — 1127 · 金灭辽：金军尽占北方，耶律大石西迁建西辽": "1125–1127 · Kim diệt Liêu: quân Kim chiếm hết phương bắc, Gia Luật Đại Thạch dời về tây lập Tây Liêu",
    "1206 — 1215 · 大蒙古国崛起：铁木真统一漠北诸部称成吉思汗": "1206–1215 · Đại Mông Cổ quốc trỗi dậy: Thiết Mộc Chân thống nhất các bộ Mạc Bắc, xưng Thành Cát Tư Hãn",
    "1215 — 1227 · 蒙古吞并金国北方：1215 攻陷金中都，金迁都汴京，黄河以北与辽东入蒙古；1218 灭西辽": "1215–1227 · Mông Cổ thôn tính phía bắc nước Kim: năm 1215 hạ Trung Đô, Kim dời đô về Biện Kinh, vùng bắc Hoàng Hà và Liêu Đông vào tay Mông Cổ; năm 1218 diệt Tây Liêu",
    "1227 — 1234 · 蒙古灭西夏：西夏并入蒙古，金朝孤守河南蔡州": "1227–1234 · Mông Cổ diệt Tây Hạ: Tây Hạ nhập vào Mông Cổ, nhà Kim cô thủ Thái Châu, Hà Nam",
    "1234 — 1253 · 宋蒙联军灭金：金亡于蔡州，宋蒙直接对峙；1247 凉州会盟吐蕃归附": "1234–1253 · Liên quân Tống – Mông diệt Kim: Kim mất ở Thái Châu, Tống – Mông trực tiếp đối đầu; năm 1247 hội minh Lương Châu, Thổ Phồn quy phụ",
    "1253 — 1276 · 忽必烈灭大理：蒙古跨金沙江平大理，对南宋形成三面包围": "1253–1276 · Hốt Tất Liệt diệt Đại Lý: Mông Cổ vượt sông Kim Sa bình Đại Lý, bao vây Nam Tống ba mặt",
    "1276 — 1279 · 临安陷落与闽广行朝：元军入临安，宋室退保福州、广州至崖山": "1276–1279 · Lâm An thất thủ và triều đình lưu vong ở Mân Quảng: quân Nguyên vào Lâm An, nhà Tống lui giữ Phúc Châu, Quảng Châu rồi Nhai Sơn",
    "1681 — 1683 · 平定三藩：西南全境入清，施琅攻台前夕": "1681–1683 · Bình định Tam phiên: toàn bộ tây nam vào tay Thanh, trước khi Thi Lang đánh Đài Loan",
    "1683 — 1691 · 施琅收台湾与尼布楚条约：置台湾府，划定中俄东段边界": "1683–1691 · Thi Lang thu Đài Loan và Điều ước Nerchinsk: đặt phủ Đài Loan, hoạch định đoạn biên giới phía đông Trung – Nga",
    "1691 — 1720 · 多伦会盟定漠北：喀尔喀蒙古正式内附纳入清朝版图": "1691–1720 · Hội minh Đa Luân định Mạc Bắc: Mông Cổ Khalkha chính thức quy phụ, vào bản đồ nhà Thanh",
    "1720 — 1759 · 驱准入藏与平定青海：设驻藏大臣、西宁办事大臣，《恰克图条约》": "1720–1759 · Đuổi Chuẩn Cát Nhĩ vào Tạng và bình Thanh Hải: đặt Trú Tạng đại thần, Tây Ninh biện sự đại thần; Điều ước Kyakhta",
    "1759 — 1796 · 乾隆极盛疆域：平定准噶尔与回部，设伊犁将军统辖天山南北": "1759–1796 · Cương vực cực thịnh thời Càn Long: bình Chuẩn Cát Nhĩ và Hồi bộ, đặt Y Lê tướng quân cai quản nam bắc Thiên Sơn",
    "1796 — 1851 · 嘉道时期：白莲教起义与 1840 年鸦片战争爆发": "1796–1851 · Thời Gia Khánh – Đạo Quang: khởi nghĩa Bạch Liên giáo và Chiến tranh Nha phiến bùng nổ năm 1840",
