    "战国长城（秦·赵·燕北长城）": "Trường Thành thời Chiến Quốc (Tần · Triệu · Yên)",
    "前 403 — 前 341 · 三家分晋、田氏代齐与魏霸中原：七雄并立，巴蜀、越、中山尚存": "403–341 TCN · Tam gia phân Tấn, họ Điền thay Tề, Ngụy xưng bá Trung Nguyên: Thất hùng cùng tồn tại, Ba Thục, Việt, Trung Sơn vẫn còn",
    "前 230 — 前 229 · 秦王扫六合之首灭韩国：内史腾俘韩王安，置颍川郡": "230–229 TCN · Tần thống nhất – diệt Hàn đầu tiên: Nội sử Đằng bắt Hàn vương An, đặt quận Dĩnh Xuyên",
    "前 228 — 前 227 · 秦王扫六合之攻克邯郸灭赵：王翦破赵俘赵王迁，公子嘉北奔代郡": "228–227 TCN · Tần thống nhất – hạ Hàm Đan diệt Triệu: Vương Tiễn phá Triệu bắt Triệu vương Thiên, công tử Gia chạy lên quận Đại",
    "前 226 · 秦王扫六合之易水破燕：荆轲刺秦后王翦攻拔燕都蓟城，燕王喜东退辽东": "226 TCN · Tần thống nhất – phá Yên ở sông Dịch: sau vụ Kinh Kha, Vương Tiễn hạ Kế thành, Yên vương Hỷ lui về Liêu Đông",
    "前 225 — 前 224 · 秦王扫六合之水灌大梁灭魏：王贲引河沟灌城，魏王假出降，三晋尽入秦": "225–224 TCN · Tần thống nhất – nhấn nước Đại Lương diệt Ngụy: Vương Bí dẫn nước Hồng Câu nhấn chìm thành, Ngụy vương Giả ra hàng, đất Tam Tấn về hết tay Tần",
    "前 223 — 前 222 · 秦王扫六合之王翦六十万灭楚、王贲灭燕代：六国唯余齐国孤悬东海": "223–222 TCN · Tần thống nhất – Vương Tiễn 60 vạn quân diệt Sở, Vương Bí diệt Yên, Đại: sáu nước chỉ còn Tề trơ trọi bên biển Đông",
    "战国初期（约前350年 · 三家分晋与七雄并立）": "Đầu thời Chiến Quốc (khoảng 350 TCN · Tam gia phân Tấn và Thất hùng)",
    "前403年周威烈王册命韩、赵、魏为诸侯（《资治通鉴》开篇），前386年田氏代齐，战国七雄格局确立；魏文侯、武侯任李悝、吴起率先称雄中原，巴、蜀、越、中山与东周王畿并存。": "Năm 403 TCN Chu Uy Liệt Vương phong Hàn, Triệu, Ngụy làm chư hầu (mở đầu Tư trị thông giám); năm 386 TCN họ Điền thay họ Khương làm vua Tề, thế Thất hùng xác lập; Ngụy Văn Hầu, Vũ Hầu dùng Lý Khôi, Ngô Khởi, xưng hùng Trung Nguyên trước tiên; Ba, Thục, Việt, Trung Sơn và vương kỳ Đông Chu cùng tồn tại.",
    "战国后期（前260年 · 白起拔郢与长平之战）": "Cuối thời Chiến Quốc (260 TCN · Bạch Khởi hạ Dĩnh và trận Trường Bình)",
    "前284年乐毅率五国联军破齐；前278年秦将白起拔楚都郢置南郡，楚东迁陈郢；前260年秦赵长平决战，白起坑赵卒四十万，山东六国再难独力抗秦。": "Năm 284 TCN Nhạc Nghị dẫn liên quân năm nước phá Tề; năm 278 TCN tướng Tần Bạch Khởi hạ Dĩnh đô nước Sở, đặt Nam quận, Sở dời về Trần Dĩnh; năm 260 TCN Tần – Triệu quyết chiến ở Trường Bình, Bạch Khởi chôn sống 40 vạn quân Triệu, sáu nước Sơn Đông khó lòng một mình chống Tần.",
    "秦王政亲政前夕（前242年 · 灭周置三川、东郡与六国合纵终结）": "Trước khi Tần vương Chính thân chính (242 TCN · diệt Chu đặt Tam Xuyên, Đông quận, hợp tung sáu nước kết thúc)",
    "战国晚期（前247年 · 秦取赵晋阳、置太原郡）": "Cuối thời Chiến Quốc (247 TCN · Tần lấy Tấn Dương của Triệu, đặt quận Thái Nguyên)",
    "前248—前247年蒙骜攻赵，取榆次、新城、狼孟等三十七城，秦置太原郡，赵国晋阳旧都入秦。": "Năm 248–247 TCN Mông Ngao đánh Triệu, lấy 37 thành như Du Thứ, Tân Thành, Lang Mạnh; Tần đặt quận Thái Nguyên, cố đô Tấn Dương của Triệu vào tay Tần.",
    "秦王扫六合 · 首灭韩国（前230年 · 内史腾俘韩王安，置颍川郡）": "Tần thống nhất · diệt Hàn đầu tiên (230 TCN · Nội sử Đằng bắt Hàn vương An, đặt quận Dĩnh Xuyên)",
    "前230年（秦王政十七年），秦内史腾攻韩，俘韩王安，尽纳其地置颍川郡。韩国成为六国中第一个覆灭的诸侯国。": "Năm 230 TCN (Tần vương Chính năm thứ 17), Nội sử Đằng nhà Tần đánh Hàn, bắt Hàn vương An, thu hết đất đặt quận Dĩnh Xuyên. Hàn là nước đầu tiên trong sáu nước bị diệt.",
    "秦王扫六合 · 攻克邯郸灭赵（前228年 · 王翦破赵，公子嘉奔代）": "Tần thống nhất · hạ Hàm Đan diệt Triệu (228 TCN · Vương Tiễn phá Triệu, công tử Gia chạy sang Đại)",
    "前228年（秦王政十九年），王翦大破赵军攻克邯郸，俘赵王迁；赵公子嘉率宗族奔代称代王，与燕联兵拒秦。": "Năm 228 TCN (Tần vương Chính năm thứ 19), Vương Tiễn đại phá quân Triệu, hạ Hàm Đan, bắt Triệu vương Thiên; công tử Gia của Triệu dẫn tông tộc chạy sang Đại xưng Đại vương, cùng Yên liên binh chống Tần.",
    "秦王扫六合 · 易水破燕拔蓟城（前226年 · 燕王喜东保辽东）": "Tần thống nhất · phá Yên ở sông Dịch, hạ Kế thành (226 TCN · Yên vương Hỷ lui giữ Liêu Đông)",
    "前227年荆轲刺秦不果，王翦、辛胜大破燕代联军于易水之西，前226年十月攻拔燕都蓟城，燕王喜斩太子丹首级献秦，退保辽东襄平。": "Năm 227 TCN Kinh Kha hành thích Tần vương bất thành, Vương Tiễn, Tân Thắng đại phá liên quân Yên – Đại ở phía tây sông Dịch; tháng mười năm 226 TCN hạ Kế thành, kinh đô nước Yên; Yên vương Hỷ chém đầu thái tử Đan dâng Tần, lui giữ Tương Bình ở Liêu Đông.",
    "秦王扫六合 · 水灌大梁灭魏（前225年 · 三晋尽入于秦）": "Tần thống nhất · nhấn nước Đại Lương diệt Ngụy (225 TCN · đất Tam Tấn về hết tay Tần)",
    "前225年（秦王政二十二年），王贲引黄河、鸿沟之水灌魏都大梁，三月城坏，魏王假出降，魏国灭亡，三晋故地尽归于秦。": "Năm 225 TCN (Tần vương Chính năm thứ 22), Vương Bí dẫn nước Hoàng Hà, Hồng Câu nhấn chìm Đại Lương, kinh đô nước Ngụy; ba tháng sau thành vỡ, Ngụy vương Giả ra hàng, nước Ngụy mất, đất cũ Tam Tấn về hết tay Tần.",
    "秦王扫六合 · 灭楚平燕代，唯余齐国（前223—前222年）": "Tần thống nhất · diệt Sở, bình Yên, Đại, chỉ còn nước Tề (223–222 TCN)",
    "前223年王翦、蒙武统六十万大军破楚拔寿春，俘楚王负刍；前222年王贲攻灭辽东燕王喜与代王嘉，王翦悉定江南置会稽郡，六国唯余东海之滨的齐国孤悬。": "Năm 223 TCN Vương Tiễn, Mông Vũ thống lĩnh 60 vạn quân phá Sở, hạ Thọ Xuân, bắt Sở vương Phụ Sô; năm 222 TCN Vương Bí diệt Yên vương Hỷ ở Liêu Đông và Đại vương Gia, Vương Tiễn bình định hết Giang Nam, đặt quận Cối Kê; sáu nước chỉ còn Tề trơ trọi bên bờ biển Đông.",
    "秦都（前350孝公迁此）": "Kinh đô nước Tần (Hiếu Công dời về đây năm 350 TCN)",
