    "辽吉（日军侵占）": "Liêu Ninh & Cát Lâm (Nhật chiếm đóng)",
    "北洋政府 · 皖系（段祺瑞）": "Chính phủ Bắc Dương · phái Hoãn (Đoàn Kỳ Thụy)",
    "直系（冯国璋 · 曹锟）": "Phái Trực Lệ (Phùng Quốc Chương · Tào Côn)",
