    "西北诸马（甘宁青）": "Các họ Mã tây bắc (Cam · Ninh · Thanh)",
    "北洋政府 · 直系（曹锟 · 吴佩孚）": "Chính phủ Bắc Dương · phái Trực Lệ (Tào Côn · Ngô Bội Phu)",
    "皖系（卢永祥 · 浙江）": "Phái Hoãn (Lư Vĩnh Tường · Chiết Giang)",
    "广州政府（孙中山）": "Chính phủ Quảng Châu (Tôn Trung Sơn)",
    "西南川滇黔桂各系": "Các phái tây nam (Xuyên · Điền · Kiềm · Quế)",
