    "川滇黔军阀（刘湘 · 唐继尧）": "Quân phiệt Xuyên Điền Kiềm (Lưu Tương · Đường Kế Nghiêu)",
    "国民政府（北伐军）": "Chính phủ Quốc dân (quân Bắc phạt)",
    "国民政府（北伐军与冯阎集团）": "Chính phủ Quốc dân (quân Bắc phạt và tập đoàn Phùng – Diêm)",
    "安国军政府 · 奉系（张作霖）": "Chính phủ An Quốc quân · phái Phụng Thiên (Trương Tác Lâm)",
    "1912 — 1915 · 民初共和与北京临时政府：清帝退位南北议和，中华民国建立": "1912–1915 · Cộng hòa đầu thời Dân Quốc và Chính phủ lâm thời Bắc Kinh: vua Thanh thoái vị, nam bắc nghị hòa, Trung Hoa Dân Quốc thành lập",
    "1916 — 1919 · 袁世凯病逝与北洋军阀割据：皖系段祺瑞掌北京中枢，直系、奉系兴起，孙中山于广州护法南北对峙": "1916–1919 · Viên Thế Khải mất, quân phiệt Bắc Dương cát cứ: phái Hoãn của Đoàn Kỳ Thụy nắm trung ương Bắc Kinh, phái Trực, phái Phụng nổi lên, Tôn Trung Sơn hộ pháp ở Quảng Châu, nam bắc đối đầu",
    "1920 — 1923 · 直皖与第一次直奉战争：曹锟、吴佩孚直系独霸北京与长江，张作霖退守关外，孙中山重建广州大元帅府": "1920–1923 · Chiến tranh Trực – Hoãn và Trực – Phụng lần thứ nhất: phái Trực của Tào Côn, Ngô Bội Phu độc chiếm Bắc Kinh và Trường Giang, Trương Tác Lâm lui ra ngoài quan ải, Tôn Trung Sơn lập lại Đại nguyên soái phủ ở Quảng Châu",
    "1924 — 1925 · 北伐前夕六大派系：奉系张作霖入关、孙传芳五省联军、直系吴佩孚、冯玉祥国民军与两广国民政府对峙": "1924–1925 · Sáu phe lớn trước Bắc phạt: Trương Tác Lâm phái Phụng vào quan ải, liên quân năm tỉnh của Tôn Truyền Phương, Ngô Bội Phu phái Trực, Quốc dân quân của Phùng Ngọc Tường và Chính phủ Quốc dân Lưỡng Quảng đối đầu nhau",
    "1926 · 北伐出师：国民革命军连克长沙、武昌、南昌、福州，孙传芳退保苏浙皖，吴佩孚困守河南，冯玉祥五原誓师入陕": "1926 · Xuất quân Bắc phạt: Quốc dân Cách mạng quân liên tiếp hạ Trường Sa, Vũ Xương, Nam Xương, Phúc Châu; Tôn Truyền Phương lui giữ Tô Chiết Hoãn, Ngô Bội Phu bị vây ở Hà Nam, Phùng Ngọc Tường thề quân ở Ngũ Nguyên tiến vào Thiểm Tây",
    "1927 · 国民革命军北伐：克上海、定都南京，冯玉祥与阎锡山响应，与奉系张作霖安国军隔河对峙": "1927 · Quốc dân Cách mạng quân Bắc phạt: hạ Thượng Hải, định đô Nam Kinh; Phùng Ngọc Tường và Diêm Tích Sơn hưởng ứng, đối đầu An Quốc quân của Trương Tác Lâm qua sông",
    "1928 — 1930 · 东北易帜与北伐完成：张学良通电易帜，南京国民政府完成形式统一": "1928–1930 · Đông Bắc đổi cờ và hoàn thành Bắc phạt: Trương Học Lương tuyên bố đổi cờ, Chính phủ Quốc dân Nam Kinh thống nhất về hình thức",
    "1931 · 九一八事变：日军关东军突袭沈阳北大营，侵占辽宁、吉林两省": "1931 · Sự biến 18 tháng 9: quân Quan Đông của Nhật tập kích Bắc Đại doanh ở Thẩm Dương, chiếm hai tỉnh Liêu Ninh, Cát Lâm",
    "1932 — 1944 · 伪满洲国建立与抗日战争：日本扶植溥仪在长春建伪“满洲国”，东北四省沦陷": "1932–1944 · Lập ngụy Mãn Châu quốc và kháng chiến chống Nhật: Nhật dựng Phổ Nghi lập ngụy \"Mãn Châu quốc\" ở Trường Xuân, bốn tỉnh Đông Bắc bị chiếm đóng",
    "1945 · 抗战胜利台湾光复：中国收回台湾、澎湖与东北四省，“秋海棠”版图重光": "1945 · Kháng chiến thắng lợi, Đài Loan được thu hồi: Trung Quốc lấy lại Đài Loan, Bành Hồ và bốn tỉnh Đông Bắc, bản đồ \"lá thu hải đường\" trở lại",
    "1946 — 1949 · 承认外蒙古独立与解放战争：外蒙古正式脱离中国，版图由“秋海棠”变为“雄鸡”": "1946–1949 · Công nhận Ngoại Mông độc lập và chiến tranh giải phóng: Ngoại Mông chính thức tách khỏi Trung Quốc, bản đồ từ \"lá thu hải đường\" thành \"con gà trống\"",
    "静海军（交州）": "Tĩnh Hải quân (Giao Châu)",
    "前 214 — 前 206 · 秦平百越与大一统鼎盛：设桂林、象、南海三郡，北筑万里长城": "214–206 TCN · Tần bình Bách Việt, đế quốc thống nhất đạt đỉnh cao: đặt ba quận Quế Lâm, Tượng, Nam Hải, phía bắc xây Vạn Lý Trường Thành",
    "前 206 — 前 202 · 秦亡与楚汉相争：陈胜起义后赵、燕、齐复国，项羽分封十八诸侯，秦将赵佗据岭南立南越、无诸复立闽越，刘邦还定三秦与项羽争霸": "206–202 TCN · Tần mất và Hán – Sở tranh hùng: sau khởi nghĩa Trần Thắng, Triệu, Yên, Tề phục quốc; Hạng Vũ phong 18 chư hầu; tướng Tần Triệu Đà giữ Lĩnh Nam lập Nam Việt, Vô Chư lập lại Mân Việt; Lưu Bang bình định Tam Tần, tranh bá với Hạng Vũ",
    "8 — 23 · 王莽代汉建新：托古改制与西域断绝，北疆匈奴复叛，绿林赤眉起兵": "8–23 · Vương Mãng thay Hán lập Tân: cải chế theo lối cổ, Tây Vực đứt liên lạc, Hung Nô ở biên bắc lại phản, Lục Lâm, Xích Mi khởi binh",
    "23 — 25 · 绿林赤眉起义与更始政权：绿林军拥立汉宗室刘玄为更始帝入长安，宗室刘秀以大司马徇河北独立发展，赤眉军与陇蜀群雄并起": "23–25 · Khởi nghĩa Lục Lâm, Xích Mi và chính quyền Canh Thủy: quân Lục Lâm tôn tông thất nhà Hán Lưu Huyền làm Canh Thủy Đế vào Trường An; tông thất Lưu Tú với chức Đại tư mã kinh lược Hà Bắc, phát triển độc lập; quân Xích Mi và quần hùng Lũng Thục cùng nổi lên",
    "848 — 880 · 张议潮归义军收复河西：沙州起义驱逐吐蕃，收复瓜沙等十一州归唐": "848–880 · Quy Nghĩa quân của Trương Nghị Triều thu hồi Hà Tây: khởi nghĩa ở Sa Châu đánh đuổi Thổ Phồn, thu lại mười một châu Qua, Sa… về với Đường",
    "880 — 884 · 黄巢攻入长安称帝大齐：黄巢大军渡江破洛阳、入长安建国号大齐，唐僖宗奔蜀，李克用等会诸镇收复长安": "880–884 · Hoàng Sào đánh vào Trường An xưng đế nước Đại Tề: đại quân Hoàng Sào vượt sông phá Lạc Dương, vào Trường An lập quốc hiệu Đại Tề; Đường Hy Tông chạy vào Thục; Lý Khắc Dụng hội các trấn thu lại Trường An",
    "885 — 907 · 唐末藩镇彻底裂解：朱温据宣武河南、李克用据河东、王建据西川、杨行密据淮南、钱镠据两浙，唐室仅存关中一隅": "885–907 · Phiên trấn cuối thời Đường tan rã hoàn toàn: Chu Ôn giữ Tuyên Vũ, Hà Nam; Lý Khắc Dụng giữ Hà Đông; Vương Kiến giữ Tây Xuyên; Dương Hành Mật giữ Hoài Nam; Tiền Lưu giữ Lưỡng Chiết; nhà Đường chỉ còn một góc Quan Trung",
